#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-09-15
"""Fig. 3b for the WiP paper: the entity layer around Autoware's obstacle-segmentation
chain, drawn with only the paper's edge kinds (sub, join, polled-msg) and a matching
legend. Data: session fish_20260913_014334 (final campaign, LTTng+nsys #1), read from
the stored graph and summarised by hand below (see the queries in the session log)."""
import sys
RANKDIR = sys.argv[1] if len(sys.argv) > 1 else "LR"
OUT = sys.argv[2] if len(sys.argv) > 2 else "fig3b_chain"
NOCONCAT = len(sys.argv) > 3 and sys.argv[3] == "noconcat"
SUB, TMR = '#F9E79F', '#AED6F1'
GPU = 'color="#d62728" penwidth=2.2'
L = ['digraph fig3b {',
     '  rankdir=' + RANKDIR + '; newrank=true; nodesep=0.12; ranksep=0.35; splines=true;',
     '  graph [fontname="Helvetica" fontsize=10 bgcolor="white"];',
     '  node  [shape=box style="filled,rounded" fontname="Helvetica" fontsize=9 color="#555555" penwidth=1 margin="0.08,0.04"];',
     '  edge  [fontname="Helvetica" fontsize=8 color="#222222" penwidth=1.2 arrowsize=0.7];']
def cluster(cid, label, other, body):
    style = 'style="rounded,dashed" color="#999999" fontcolor="#666666"' if other else 'style="rounded" color="#444444"'
    L.append(f'  subgraph cluster_{cid} {{ label="{label}"; {style}; fontsize=9;')
    L.extend('    ' + b for b in body); L.append('  }')
def ent(id_, label, kind, gpu=False, polled=False):
    fill = SUB if kind == 'sub' else TMR
    extra = f' {GPU}' if gpu else ''
    lab = label + ('\\n(polled)' if polled else '')
    return f'{id_} [label="{lab}" fillcolor="{fill}"{extra}];'
if not NOCONCAT:
    cluster('concat', 'concatenate_data  (/sensing/lidar)', True, [
        ent('c_top', 'sub top cloud', 'sub'),
        ent('c_left', 'sub left cloud', 'sub'),
        ent('c_right', 'sub right cloud', 'sub'),
        ent('c_tmr', 'tmr 200 ms (x3)', 'tmr'),
        'c_left -> c_top [style=dotted color="#1f77b4" dir=none penwidth=1.4 label="join"];',
        'c_right -> c_top [style=dotted color="#1f77b4" dir=none penwidth=1.4];',
        'c_tmr -> c_top [style=dotted color="#1f77b4" dir=none penwidth=1.4];'])
else:
    L.append('  ext_in [shape=cds style=filled fillcolor="#e6e6e6" color="#999999" fontcolor="#333333" label="concatenate_data\\n(/sensing/lidar)"];')
cluster('crop', 'crop_box_filter', False, [ent('crop', 'sub concatenated cloud', 'sub')])
cluster('ground', 'common_ground_filter', False, [ent('ground', 'sub range_cropped cloud', 'sub')])
cluster('ogm', 'occupancy_grid_map_node  (/perception/occupancy_grid_map)', True, [
    ent('ogm_pc', 'sub concatenated cloud', 'sub', gpu=True),
    ent('ogm_sf', 'sub single_frame cloud', 'sub', gpu=True),
    'ogm_pc -> ogm_sf [style=dotted color="#1f77b4" dir=none penwidth=1.4 label="join"];'])
cluster('outlier', 'occupancy_grid_based_outlier_filter', False, [
    ent('out_sf', 'sub single_frame cloud', 'sub'), ent('out_map', 'sub occupancy map', 'sub')])
cluster('aeb', 'autonomous_emergency_braking  (/control)', True, [
    ent('aeb_sub', 'sub obstacle cloud', 'sub', polled=True), ent('aeb_tmr', 'tmr 100 ms', 'tmr'),
    'aeb_sub -> aeb_tmr [style=dashed color="#e07b00" penwidth=1.6 arrowhead=onormal label="polled-msg\\nage 108 ms"];'])
# sub edges: from the publishing entity to the subscription
if NOCONCAT:
    L.append('  ext_in -> crop [label="concatenated cloud"];'); L.append('  ext_in -> ogm_pc;')
else:
    for s in ('c_top', 'c_left', 'c_tmr'):
        L.append(f'  {s} -> crop [label="{"concatenated cloud" if s == "c_top" else ""}"];')
        L.append(f'  {s} -> ogm_pc;')
L.append('  crop -> ground [label="range_cropped cloud"];')
L.append('  ground -> out_sf [label="single_frame cloud"];')
L.append('  ground -> ogm_sf;')
L.append('  ogm_pc -> out_map [label="occupancy map\\nhop 0.7 ms"];')
L.append('  ogm_sf -> out_map;')
L.append('  out_map -> aeb_sub [label="obstacle cloud\\nhop 0.2 ms"];')
# legend
L.append('''  legend [shape=box style="filled" fillcolor="white" color="#999999" margin=0.04 label=<
<TABLE BORDER="0" CELLBORDER="0" CELLSPACING="2" CELLPADDING="2">
<TR><TD BGCOLOR="#F9E79F" WIDTH="18"></TD><TD ALIGN="LEFT">sub</TD>
    <TD BGCOLOR="#AED6F1" WIDTH="18"></TD><TD ALIGN="LEFT">tmr</TD>
    <TD BORDER="2" COLOR="#d62728" WIDTH="18"></TD><TD ALIGN="LEFT">submits GPU work</TD>
    <TD BORDER="1" COLOR="#999999" STYLE="dashed" WIDTH="18"></TD><TD ALIGN="LEFT">other namespace</TD></TR>
<TR><TD><FONT COLOR="#222222">&#9472;&#9472;&#9654;</FONT></TD><TD ALIGN="LEFT">sub</TD>
    <TD><FONT COLOR="#1f77b4">&#8230;&#8230;&#8230;</FONT></TD><TD ALIGN="LEFT">join</TD>
    <TD><FONT COLOR="#e07b00">&#8211; &#8211; &#9655;</FONT></TD><TD ALIGN="LEFT">polled-msg</TD>
    <TD></TD><TD ALIGN="LEFT">hop / age: measured p50</TD></TR>
</TABLE>>];''')
L.append('  {rank=sink; legend;}')
L.append('}')
open(OUT + '.dot', 'w').write('\n'.join(L))
